package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ScheduleRulesTest {
 final UUID space=new UuidV7(Clock.systemUTC()).next();
 @Test void gapOverlapNormalAndHalfHourOffsetsAreExplicit(){assertTrue(ScheduleRules.options(space,"2028-03-12T02:30:00","America/New_York").options().isEmpty());var overlap=ScheduleRules.options(space,"2028-11-05T01:30:00","America/New_York");assertEquals(List.of("2028-11-05T05:30:00Z","2028-11-05T06:30:00Z"),overlap.options().stream().map(ScheduleRules.Option::instant).toList());assertEquals(List.of("-04:00","-05:00"),overlap.options().stream().map(ScheduleRules.Option::offset).toList());assertEquals("2028-10-17T00:00:00Z",ScheduleRules.options(space,"2028-10-17T09:00:00","Asia/Seoul").options().getFirst().instant());assertEquals(2,ScheduleRules.options(space,"2028-04-02T01:45:00","Australia/Lord_Howe").options().size());}
 @Test void dateWindowsHaveDstLengthsAndRejectEmptyOrExcessiveRanges(){for(var d:Map.of("2028-03-12",23,"2028-11-05",25).entrySet()){var w=ScheduleRules.window(d.getKey(),d.getKey(),"America/New_York");assertEquals(d.getValue().longValue(),Duration.between(w.start(),w.end()).toHours());}assertThrows(RuntimeException.class,()->ScheduleRules.window("2011-12-30","2011-12-30","Pacific/Apia"));assertThrows(RuntimeException.class,()->ScheduleRules.window("2028-01-02","2028-01-01","UTC"));assertThrows(RuntimeException.class,()->ScheduleRules.window("2028-01-01","2028-04-03","UTC"));assertDoesNotThrow(()->ScheduleRules.window("9999-12-31","9999-12-31","UTC"));}
 @Test void strictUtcWholeSecondsZonesTextAndIntervals(){for(String s:List.of("2028-01-01T00:00:00+00:00","2028-01-01T00:00:00.000Z","0000-01-01T00:00:00Z","2028-01-01T24:00:00Z","2028-02-30T00:00:00Z","2028-01-01T23:59:60Z"))assertThrows(RuntimeException.class,()->ScheduleRules.instant(s));for(String z:List.of("+09:00","Mars/Olympus","","UTC "))assertThrows(RuntimeException.class,()->ScheduleRules.zone(z));assertThrows(RuntimeException.class,()->ScheduleRules.input(new ScheduleStore.Input("Title","","2028-01-01T00:00:00Z","2028-01-01T00:00:00Z","UTC",null)));assertThrows(RuntimeException.class,()->ScheduleRules.input(new ScheduleStore.Input(" ","","2028-01-01T00:00:00Z","2028-01-01T01:00:00Z","UTC",null)));}
 @Test void cursorIsCanonicalAndBoundToEveryScopeAndFilter(){var id=new UuidV7(Clock.systemUTC()).next();var w=ScheduleRules.window("2028-10-01","2028-10-31","UTC");var raw=ScheduleRules.cursor(space,"ACTIVE","ALL",w,"2028-10-17T00:00:00Z",id);assertEquals(id,ScheduleRules.cursor(raw,space,"ACTIVE","ALL",w).id());for(String bad:List.of(raw+"=","!bad","YQ"))assertThrows(RuntimeException.class,()->ScheduleRules.cursor(bad,space,"ACTIVE","ALL",w));assertThrows(RuntimeException.class,()->ScheduleRules.cursor(raw,id,"ACTIVE","ALL",w));assertThrows(RuntimeException.class,()->ScheduleRules.cursor(raw,space,"RETIRED","ALL",w));assertThrows(RuntimeException.class,()->ScheduleRules.cursor(raw,space,"ACTIVE","NONE",w));assertThrows(RuntimeException.class,()->ScheduleRules.cursor(raw,space,"ACTIVE","ALL",ScheduleRules.window("2028-10-02","2028-10-31","UTC")));assertThrows(RuntimeException.class,()->ScheduleRules.cursor(raw,space,"ACTIVE","ALL",ScheduleRules.window("2028-10-01","2028-10-31","Asia/Seoul")));}
}
